"use client";

import { useEffect, useId, useRef, useState } from "react";
import Link from "next/link";

type MenuItem = {
  label: string;
  href: string;
};

type MobileMenuProps = {
  items: MenuItem[];
};

export function MobileMenu({ items }: MobileMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const dialogRef = useRef<HTMLDialogElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const titleId = useId();

  useEffect(() => {
    const dialog = dialogRef.current;

    if (!dialog) return;

    if (isOpen && !dialog.open) {
      dialog.showModal();
    }

    if (!isOpen && dialog.open) {
      dialog.close();
    }
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) return;

    const body = document.body;
    const root = document.documentElement;
    const scrollY = window.scrollY;
    const scrollbarWidth = window.innerWidth - root.clientWidth;

    const previousStyles = {
      overflow: body.style.overflow,
      position: body.style.position,
      top: body.style.top,
      width: body.style.width,
      paddingRight: body.style.paddingRight,
    };

    body.style.overflow = "hidden";
    body.style.position = "fixed";
    body.style.top = `-${scrollY}px`;
    body.style.width = "100%";

    if (scrollbarWidth > 0) {
      body.style.paddingRight = `${scrollbarWidth}px`;
    }

    return () => {
      body.style.overflow = previousStyles.overflow;
      body.style.position = previousStyles.position;
      body.style.top = previousStyles.top;
      body.style.width = previousStyles.width;
      body.style.paddingRight = previousStyles.paddingRight;

      window.scrollTo({
        top: scrollY,
        left: 0,
        behavior: "instant",
      });
    };
  }, [isOpen]);

  function closeMenu() {
    setIsOpen(false);
    requestAnimationFrame(() => triggerRef.current?.focus());
  }

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={isOpen}
        aria-controls={titleId}
        onClick={() => setIsOpen(true)}
        className="grid size-11 place-items-center rounded-full border border-current md:hidden"
      >
        <span className="sr-only">Abrir menú</span>

        <svg
          aria-hidden="true"
          viewBox="0 0 24 24"
          className="size-5"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.75"
        >
          <path d="M4 8h16M4 16h16" />
        </svg>
      </button>

      <dialog
        ref={dialogRef}
        id={titleId}
        aria-label="Menú principal"
        onCancel={(event) => {
          event.preventDefault();
          closeMenu();
        }}
        onClose={() => setIsOpen(false)}
        onClick={(event) => {
          if (event.target === event.currentTarget) closeMenu();
        }}
        className="
          fixed inset-0 m-0 h-[100svh] max-h-none w-screen max-w-none
          border-0 bg-neutral-950 p-0 text-neutral-50
          backdrop:bg-transparent
          open:flex open:flex-col
        "
      >
        <header className="flex h-20 shrink-0 items-center justify-between px-6">
          <span className="text-sm font-medium uppercase tracking-[0.16em]">
            Menú
          </span>

          <button
            type="button"
            autoFocus
            onClick={closeMenu}
            className="grid size-11 place-items-center rounded-full border border-white/30"
          >
            <span className="sr-only">Cerrar menú</span>

            <svg
              aria-hidden="true"
              viewBox="0 0 24 24"
              className="size-5"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
            >
              <path d="m5 5 14 14M19 5 5 19" />
            </svg>
          </button>
        </header>

        <nav
          aria-label="Navegación móvil"
          className="flex flex-1 items-center px-6 py-10"
        >
          <ul className="w-full">
            {items.map((item, index) => (
              <li key={item.href} className="border-b border-white/15">
                <Link
                  href={item.href}
                  onClick={closeMenu}
                  className="
                    flex min-h-16 items-center justify-between py-4
                    text-[clamp(2rem,10vw,4rem)] leading-none
                    transition-opacity duration-200 hover:opacity-60
                    focus-visible:outline-2 focus-visible:outline-offset-4
                    focus-visible:outline-white
                  "
                >
                  <span>{item.label}</span>
                  <span
                    aria-hidden="true"
                    className="text-xs tabular-nums text-white/45"
                  >
                    {String(index + 1).padStart(2, "0")}
                  </span>
                </Link>
              </li>
            ))}
          </ul>
        </nav>
      </dialog>
    </>
  );
}
```

Uso:

```tsx
<MobileMenu
  items={[
    { label: "Inicio", href: "/" },
    { label: "Proyectos", href: "/proyectos" },
    { label: "Contacto", href: "/contacto" },
  ]}
/>
```

Usa `<dialog>` nativo para focus trap y Escape. El bloqueo conserva la posición, evita el salto de la scrollbar y restaura exactamente los estilos previos del `body` al cerrar.
